// Lê o webhook da Evolution (v2) e devolve só o que interessa.
// Ignora grupos, status, canais, reações e eventos que não são mensagem.
const out = [];
for (const it of $input.all()) {
  const b = it.json.body || it.json;
  const ev = String(b.event || '').toLowerCase().replace(/_/g, '.');
  if (ev !== 'messages.upsert') continue;
  const d = Array.isArray(b.data) ? b.data[0] : b.data;
  if (!d || !d.key) continue;
  let jid = d.key.remoteJid || '';
  if (jid.endsWith('@lid')) jid = d.key.remoteJidAlt || d.key.senderPn || '';
  if (!jid.endsWith('@s.whatsapp.net')) continue;
  const m = d.message || {};
  if (m.protocolMessage || m.reactionMessage || m.pollUpdateMessage) continue;
  let texto = m.conversation || (m.extendedTextMessage && m.extendedTextMessage.text) ||
    (m.imageMessage && m.imageMessage.caption) || (m.videoMessage && m.videoMessage.caption) ||
    (m.documentMessage && m.documentMessage.caption) ||
    (m.buttonsResponseMessage && m.buttonsResponseMessage.selectedDisplayText) ||
    (m.listResponseMessage && m.listResponseMessage.title) || '';
  let tipo = 'texto';
  if (m.audioMessage) { tipo = 'audio'; texto = '[mandou um áudio]'; }
  else if (m.imageMessage) { tipo = 'imagem'; texto = texto ? '[imagem] ' + texto : '[mandou uma imagem sem texto]'; }
  else if (m.videoMessage) { tipo = 'video'; texto = texto ? '[vídeo] ' + texto : '[mandou um vídeo sem texto]'; }
  else if (m.stickerMessage) { tipo = 'figurinha'; texto = '[mandou uma figurinha]'; }
  else if (m.documentMessage) { tipo = 'documento'; texto = texto ? '[documento] ' + texto : '[mandou um documento]'; }
  else if (m.contactMessage || m.contactsArrayMessage) { tipo = 'contato'; texto = '[mandou um contato]'; }
  else if (m.locationMessage) { tipo = 'localizacao'; texto = '[mandou uma localização]'; }
  texto = String(texto).trim();
  if (!texto) continue;
  out.push({ json: {
    instancia: b.instance,
    msg_id: d.key.id,
    from_me: !!d.key.fromMe,
    whatsapp: jid.split('@')[0],
    nome_contato: d.pushName || '',
    tipo,
    texto,
  }});
}
return out;

// Calcula os horários livres da agenda e monta o texto que vai para a IA.
const ctx = $('Monta contexto').first().json;
const tz = 'America/Sao_Paulo';
const cfg = ctx.cfg || {};
const lead = ctx.lead || {};
const nicho = ctx.nicho || {};
const h = Object.assign({ dias: [1,2,3,4,5], inicio: '09:00', fim: '18:00', almoco: ['12:00','13:30'], duracao: 30, antecedencia_horas: 3 }, cfg.horarios || {});
// Janela em que o especialista pode chamar o lead na hora (padrão: seg a sex, 8h às 18h)
const plantao = Object.assign({ dias: [1,2,3,4,5], inicio: '08:00', fim: '18:00' }, (cfg.horarios && cfg.horarios.plantao) || {});
const dias = ['seg','ter','qua','qui','sex','sáb','dom'];
const rotulo = (t) => `${dias[t.weekday - 1]} ${t.toFormat('dd/MM')} às ${t.toFormat("HH'h'mm")}`;
const agora = DateTime.now().setZone(tz);
const hhmm = agora.toFormat('HH:mm');
const disponivelAgora = cfg.tipo !== undefined && plantao.dias.includes(agora.weekday) && hhmm >= plantao.inicio && hhmm < plantao.fim;

let slots = [];
const statusAgenda = ['respondeu','interessado','novo','contatado','sem_interesse'];
const itens = $input.all().map(i => i.json);
const erroAgenda = itens.some(e => e && e.error);
if (cfg.agenda_id && statusAgenda.includes(lead.status) && !erroAgenda) {
  const busy = itens
    .filter(e => e && e.start && e.status !== 'cancelled' && e.transparency !== 'transparent')
    .map(e => ({
      s: DateTime.fromISO(e.start.dateTime || e.start.date, { zone: tz }),
      e: DateTime.fromISO(e.end.dateTime || e.end.date, { zone: tz }),
    }));
  const min = agora.plus({ hours: h.antecedencia_horas });
  const hm = (s) => { const [a, b] = String(s).split(':').map(Number); return { hour: a, minute: b || 0, second: 0, millisecond: 0 }; };
  for (let d = 0; d < 21 && slots.length < 8; d++) {
    const dia = agora.plus({ days: d }).startOf('day');
    if (!h.dias.includes(dia.weekday)) continue;
    let t = dia.set(hm(h.inicio));
    const fim = dia.set(hm(h.fim));
    const a1 = h.almoco ? dia.set(hm(h.almoco[0])) : null;
    const a2 = h.almoco ? dia.set(hm(h.almoco[1])) : null;
    let n = 0;
    while (t.plus({ minutes: h.duracao }) <= fim && n < 3 && slots.length < 8) {
      const te = t.plus({ minutes: h.duracao });
      const livre = t >= min && !(a1 && t < a2 && te > a1) && !busy.some(b => t < b.e && te > b.s);
      if (livre) {
        slots.push({ inicio: t.toISO({ suppressMilliseconds: true }), rotulo: rotulo(t) });
        n++;
        t = t.plus({ minutes: 120 });
      } else {
        t = t.plus({ minutes: 30 });
      }
    }
  }
}

const hist = Array.isArray(ctx.historico) ? ctx.historico : [];
const nome = (a) => a === 'lead' ? 'Lead' : a === 'humano' ? `WEAP (${cfg.responsavel_nome}, escrito por ele)` : a === 'disparo' ? 'WEAP (mensagem de prospecção)' : 'WEAP (assistente)';
let ultimoOut = -1;
hist.forEach((m, i) => { if (m.autor !== 'lead') ultimoOut = i; });
const antigas = hist.slice(0, ultimoOut + 1);
const novas = hist.slice(ultimoOut + 1).filter(m => m.autor === 'lead');
const linha = (m) => `[${m.quando}] ${nome(m.autor)}: ${m.texto}`;
const midias = Array.isArray(ctx.midias) ? ctx.midias : [];
const proposto = lead.horario_proposto ? rotulo(DateTime.fromISO(lead.horario_proposto).setZone(tz)) : '';

const prompt = [
  '# NÚMERO DA WEAP NESTA CONVERSA',
  `Responsável: ${cfg.responsavel_nome || 'equipe WEAP'}`,
  `Cidade: ${cfg.cidade || 'não informada'}`,
  `Tipo: ${cfg.tipo === 'trafego' ? 'tráfego (o lead veio de um anúncio da WEAP)' : 'prospecção (a WEAP mandou a primeira mensagem)'}`,
  `Modo de agenda: ${cfg.modo_agenda || 'sugerir'}`,
  `ESPECIALISTA DISPONÍVEL AGORA: ${disponivelAgora ? 'sim' : 'não'}`,
  '',
  '# LEAD',
  `Empresa: ${lead.nome_empresa || 'não informada'}`,
  `Nome no WhatsApp: ${lead.nome_contato || 'não informado'}`,
  `Especialidades no Google Maps: ${lead.especialidades || 'não informadas'}`,
  `Nicho: ${lead.nicho || 'geral'}`,
  `Status atual: ${lead.status || 'novo'}`,
  `Resumo até agora: ${lead.resumo || 'nenhum'}`,
  `Horário já escolhido aguardando confirmação: ${lead.status === 'agendamento_pendente' && proposto ? proposto : 'nenhum'}`,
  `Reunião marcada: ${lead.status === 'agendado' && proposto ? proposto : 'nenhuma'}`,
  '',
  '# REGRAS DO NICHO',
  nicho.regras || 'Sem promessa de resultado, sem preço.',
  `Frentes que mais fazem sentido: ${nicho.frentes || 'site, gestão de redes, tráfego pago, manual de marca'}`,
  '',
  '# MÍDIAS DISPONÍVEIS',
  midias.length ? midias.map(m => `- id ${m.id} (${m.tipo === 'video' ? 'vídeo' : 'imagem'}): ${m.descricao}`).join('\n') : 'nenhuma',
  '',
  '# HORÁRIOS LIVRES (conversa de ' + h.duracao + ' minutos)',
  !cfg.agenda_id ? 'agenda não configurada: não proponha horários'
    : erroAgenda ? 'agenda indisponível agora: não proponha horários; se a pessoa quiser conversar, use passar_humano'
    : !statusAgenda.includes(lead.status) ? 'não ofereça horários nesta etapa (já existe horário escolhido, reunião marcada ou o responsável assumiu)'
    : (slots.length ? slots.map(s => `- inicio ${s.inicio} | rótulo "${s.rotulo}"`).join('\n') : 'nenhum horário livre nos próximos dias'),
  '',
  '# CONVERSA ATÉ AGORA (mais antiga primeiro)',
  antigas.length ? antigas.map(linha).join('\n') : '(nenhuma mensagem anterior registrada)',
  '',
  '# MENSAGENS NOVAS DO LEAD (responda a estas)',
  novas.map(linha).join('\n'),
  '',
  `Agora: ${dias[agora.weekday - 1]} ${agora.toFormat("dd/MM/yyyy HH'h'mm")} (horário de Brasília).`,
].join('\n');

return [{ json: { slots, prompt, disponivel_agora: disponivelAgora } }];

// Confere a resposta da IA, aplica as regras e monta o que será enviado.
const ctx = $('Monta contexto').first().json;
const prep = $('Prepara prompt').first().json;
const cfg = ctx.cfg || {};
const conf = ctx.conf || {};
const lead = ctx.lead || {};
let r = $json.message && $json.message.content;
if (typeof r === 'string') { try { r = JSON.parse(r.replace(/^```(json)?|```$/g, '').trim()); } catch (e) { r = {}; } }
r = r || {};

const acoes = ['nenhuma','propor_horarios','chamar_especialista','agendar','passar_humano','opt_out','automatica','bot'];
const statusOk = ['respondeu','interessado','agendamento_pendente','agendado','sem_interesse','humano'];
let acao = acoes.includes(r.acao) ? r.acao : 'nenhuma';
let resposta = String(r.resposta || '').trim();
let status = statusOk.includes(r.status) ? r.status : (lead.status === 'contatado' || lead.status === 'novo' ? 'respondeu' : lead.status);
let slot = null;

// Proteções contra robôs (independentes da IA)
const hist = Array.isArray(ctx.historico) ? ctx.historico : [];
let ultimoOut = -1;
hist.forEach((m, i) => { if (m.autor !== 'lead') ultimoOut = i; });
const novas = hist.slice(ultimoOut + 1).filter(m => m.autor === 'lead').map(m => String(m.texto || '').trim().toLowerCase());
const anteriores = hist.slice(0, ultimoOut + 1).filter(m => m.autor === 'lead').map(m => String(m.texto || '').trim().toLowerCase());
const repetida = novas.length > 0 && novas.every(t => t.length > 15 && anteriores.includes(t));
const respostasIa = hist.filter(m => m.autor === 'ia').length;
const jaConversou = hist.some(m => m.autor === 'ia' || m.autor === 'humano');
if (repetida) acao = 'bot';                       // mesma mensagem longa repetida = robô
if (respostasIa >= 25 && acao !== 'bot') acao = 'passar_humano'; // conversa longa demais: chama uma pessoa

if (acao === 'agendar') {
  const alvo = DateTime.fromISO(String(r.horario_inicio || ''));
  slot = prep.slots.find(s => s.inicio === r.horario_inicio) ||
         (alvo.isValid ? prep.slots.find(s => DateTime.fromISO(s.inicio).toMillis() === alvo.toMillis()) : null);
  if (!slot) {
    acao = prep.slots.length ? 'propor_horarios' : 'passar_humano';
    status = prep.slots.length ? 'interessado' : 'humano';
  }
}
let criar_evento = false;
if (acao === 'agendar') {
  if (cfg.modo_agenda === 'automatico') { criar_evento = true; status = 'agendado'; }
  else { acao = 'pre_agendar'; status = 'agendamento_pendente'; }
}
if (acao === 'opt_out') status = 'sem_interesse';
if (acao === 'automatica') { resposta = ''; status = jaConversou ? lead.status : 'contatado'; }
if (acao === 'bot') { resposta = ''; status = 'bot'; }
if (acao === 'passar_humano' || acao === 'chamar_especialista') status = 'humano';

const midias = Array.isArray(ctx.midias) ? ctx.midias : [];
const midia = (r.midia_id != null && resposta) ? (midias.find(m => String(m.id) === String(r.midia_id)) || null) : null;

const token = (lead.token && String(lead.token).length >= 20) ? lead.token
  : Array.from({ length: 32 }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');

const base = String(conf.webhook_base || '').replace(/\/$/, '');
const linkConfirmar = `${base}/weap-agente-acao?a=confirmar&l=${lead.id}&t=${token}`;
const linkRetomar = `${base}/weap-agente-acao?a=retomar&l=${lead.id}&t=${token}`;
const quem = `${lead.nome_empresa || lead.nome_contato || 'Lead'}${lead.nicho && lead.nicho !== 'geral' ? ' (' + lead.nicho + ')' : ''}`;
const wa = `https://wa.me/${lead.whatsapp || ''}`;
const resumo = String(r.resumo || lead.resumo || '').trim();

let aviso = '';
if (acao === 'pre_agendar') {
  aviso = `📅 ${quem} quer conversar ${slot.rotulo}.\nResumo: ${resumo}\nConversa: ${wa} (número ${lead.instancia})\n\nPara CONFIRMAR e já avisar o lead: ${linkConfirmar}\n\nSe não puder nesse horário, responda o lead direto no WhatsApp. A IA para de responder esse contato sozinha.`;
} else if (acao === 'chamar_especialista') {
  aviso = `🔥 CHAME AGORA: ${quem} aceitou falar com você agora pelo WhatsApp.\nO que precisa: ${r.aviso_responsavel || resumo}\nConversa: ${wa} (número ${lead.instancia})\n\nA IA parou de responder esse contato. Se não puder chamar, para a IA voltar e oferecer horários: ${linkRetomar}`;
} else if (acao === 'passar_humano') {
  aviso = `🙋 ${quem} precisa de você: ${r.aviso_responsavel || resumo}\nConversa: ${wa} (número ${lead.instancia})\nA IA parou de responder esse contato. Para reativar: ${linkRetomar}`;
} else if (status === 'interessado' && lead.status !== 'interessado') {
  aviso = `🔥 Lead interessado: ${quem}\nResumo: ${resumo}\nConversa: ${wa} (número ${lead.instancia})`;
}

return [{ json: {
  lead_id: lead.id,
  instancia: lead.instancia,
  numero: lead.whatsapp,
  resposta,
  acao,
  status,
  resumo,
  criar_evento,
  inicio: slot ? slot.inicio : '',
  fim: slot ? DateTime.fromISO(slot.inicio, { setZone: true }).plus({ minutes: (cfg.horarios && cfg.horarios.duracao) || 30 }).toISO({ suppressMilliseconds: true }) : '',
  rotulo: slot ? slot.rotulo : '',
  agenda_id: cfg.agenda_id || '',
  token,
  opt_out: acao === 'opt_out' || acao === 'bot',
  pausar: acao === 'passar_humano' || acao === 'chamar_especialista',
  midia,
  aviso,
  responsavel_whatsapp: cfg.responsavel_whatsapp || '',
  instancia_avisos: conf.instancia_avisos || '',
  evolution_url: String(conf.evolution_url || '').replace(/\/$/, ''),
  empresa: lead.nome_empresa || lead.nome_contato || 'Lead',
  responsavel_nome: cfg.responsavel_nome || 'WEAP',
}}];

