// Junta a decisão com o evento criado (quando a IA marcou sozinha).
const v = Object.assign({}, $('Valida decisão').first().json);
v.evento_id = '';
v.link_reuniao = '';
if (v.criar_evento) {
  let ev = null;
  try { ev = $('Cria evento').first().json; } catch (e) { ev = null; }
  if (ev && ev.id) {
    v.evento_id = ev.id;
    v.link_reuniao = ev.hangoutLink || ev.htmlLink || '';
    if (v.link_reuniao) v.resposta = `${v.resposta}\n\nLink da nossa conversa: ${v.link_reuniao}`.trim();
    v.aviso = `✅ Reunião marcada pela IA: ${v.empresa}, ${v.rotulo}.\nResumo: ${v.resumo}\nLink: ${v.link_reuniao}\nConversa: https://wa.me/${v.numero}`;
  } else {
    v.status = 'humano';
    v.pausar = true;
    v.aviso = `⚠️ A IA tentou marcar ${v.empresa} para ${v.rotulo}, mas não conseguiu criar o evento na agenda. Confirme com o lead: https://wa.me/${v.numero}`;
  }
}
v.tem_midia = !!(v.midia && v.midia.url);
if (v.tem_midia) {
  const url = String(v.midia.url);
  const nomeArq = url.split('?')[0].split('/').pop() || (v.midia.tipo === 'video' ? 'video.mp4' : 'imagem.jpg');
  const ext = (nomeArq.split('.').pop() || '').toLowerCase();
  const mimes = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', mp4: 'video/mp4', mov: 'video/quicktime' };
  v.midia_body = {
    number: v.numero,
    mediatype: v.midia.tipo === 'video' ? 'video' : 'image',
    mimetype: mimes[ext] || (v.midia.tipo === 'video' ? 'video/mp4' : 'image/jpeg'),
    caption: v.midia.legenda || '',
    media: url,
    fileName: nomeArq,
    delay: 1200,
  };
}
v.tem_texto = !!String(v.resposta || '').trim();
v.tem_aviso = !!(v.aviso && v.responsavel_whatsapp && v.instancia_avisos);
return [{ json: v }];

// Link "confirmar" clicado pelo responsável: monta os dados do evento e a mensagem para o lead.
const c = $('Valida link').first().json;
const lead = c.lead || {};
const cfg = c.cfg || {};
const conf = c.conf || {};
const tz = 'America/Sao_Paulo';
const dias = ['seg','ter','qua','qui','sex','sáb','dom'];
const ini = DateTime.fromISO(lead.horario_proposto).setZone(tz);
const dur = (cfg.horarios && cfg.horarios.duracao) || 30;
return [{ json: {
  lead_id: lead.id,
  instancia: lead.instancia,
  numero: lead.whatsapp,
  agenda_id: cfg.agenda_id || '',
  inicio: ini.toISO({ suppressMilliseconds: true }),
  fim: ini.plus({ minutes: dur }).toISO({ suppressMilliseconds: true }),
  rotulo: `${dias[ini.weekday - 1]} ${ini.toFormat('dd/MM')} às ${ini.toFormat("HH'h'mm")}`,
  empresa: lead.nome_empresa || lead.nome_contato || 'Lead',
  resumo: lead.resumo || '',
  responsavel_nome: cfg.responsavel_nome || 'WEAP',
  evolution_url: String(conf.evolution_url || '').replace(/\/$/, ''),
  ja_agendado: lead.status === 'agendado',
  valido: ini.isValid && ini > DateTime.now(),
}}];

